/* Expand the catalog with additional products that are linked to existing categories. */
ON DUPLICATE KEY UPDATE name=VALUES(name),price=VALUES(price),price_display=VALUES(price_display),subscription=VALUES(subscription),score=VALUES(score),verdict=VALUES(verdict),best_for=VALUES(best_for),image_url=VALUES(image_url),image_key=VALUES(image_key),alt_text=VALUES(alt_text),updated_label=VALUES(updated_label),rank_order=VALUES(rank_order),is_featured=VALUES(is_featured);

ON DUPLICATE KEY UPDATE title=VALUES(title),pick_product_id=VALUES(pick_product_id),pick_name=VALUES(pick_name),budget=VALUES(budget),tradeoff=VALUES(tradeoff),content_json=VALUES(content_json),sort_order=VALUES(sort_order);

VALUES ('petkit-eversweet-vs-catit-pixi',(SELECT id FROM categories WHERE slug='smart-water-fountains'),(SELECT id FROM products WHERE slug='petkit-eversweet-3'),(SELECT id FROM products WHERE slug='catit-pixi-smart-fountain'),'PETKIT Eversweet 3','Catit PIXI Smart Fountain','A quiet stainless-steel fountain is compared with a compact app-connected fountain; cleaning access and recurring filter cost matter more than tank size alone.',0,'7 min read','Sep 2026',JSON_OBJECT('matchType','direct-alternatives','matchLabel','Direct alternatives','whyCompare','Both target owners who want fresher water with less daily attention.','decisionQuestion','Do you value quiet stainless-steel construction or app refill reminders?'),16,FALSE,TRUE)
ON DUPLICATE KEY UPDATE product_a_id=VALUES(product_a_id),product_b_id=VALUES(product_b_id),product_a_name=VALUES(product_a_name),product_b_name=VALUES(product_b_name),verdict=VALUES(verdict),updated_label=VALUES(updated_label),content_json=VALUES(content_json),is_published=TRUE;
